from datetime import datetime, timedelta
from security_models import KeyUsageSummaryConfig
from security_client import get_cloudtrail_client

def summarize_key_usage(config: KeyUsageSummaryConfig, lookup_attributes: list = None):
    client = get_cloudtrail_client(config.aws_region)

    if lookup_attributes is None:
        lookup_attributes = []

    # Example: Look for KMS events in the last 24 hours
    end_time = datetime.utcnow()
    start_time = end_time - timedelta(hours=24)

    events = []
    paginator = client.get_paginator('lookup_events')
    response_iterator = paginator.paginate(
        LookupAttributes=lookup_attributes, 
        StartTime=start_time,
        EndTime=end_time
    )

    for page in response_iterator:
        for event in page['Events']:
            if 'KMS' in event.get('EventSource', ''):
                events.append(event)

    summary = {
        "total_kms_events": len(events),
        "events": events
    }
    return summary

from security_models import CryptoAuditEmbeddingConfig
from security_client import get_cohere_client

def embed_audit_notes(audit_notes: list[str], config: CryptoAuditEmbeddingConfig):
    client = get_cohere_client(config.cohere_api_key)

    response = client.embed(
        texts=audit_notes,
        model=config.model,
        input_type="search_document"
    )

    return {"embeddings": response.embeddings}

from security_models import ComplianceNoteTranslateConfig
from security_client import get_translate_client

def translate_compliance_notes(notes: list[str], config: ComplianceNoteTranslateConfig):
    client = get_translate_client(config.aws_region)
    translated_notes = []

    for note in notes:
        response = client.translate_text(
            Text=note,
            SourceLanguageCode=config.source_language_code,
            TargetLanguageCode=config.target_language_code,
        )
        translated_notes.append(response["TranslatedText"])

    return {"translated_notes": translated_notes}
